#ifndef SHANKPIT_COZY_H
#define SHANKPIT_COZY_H

/* cozy.h -- the two small joys, in SHANKPIT. The host half of PARENA's stdlib/shankpit/cozy_rules.prn.
 *
 * The DECISIONS are not here: when a dandelion may be kicked, how long a tree's hug lasts, what each is worth and
 * how fast the comfort drains are all in the .prn, emitted to packages/simulation/cozy_rules.c (generated by
 * scripts/gen_cozy_rules.sh, do not edit) and to Luau for NOOBTOPIA from the same file. This header is the thin
 * host: it owns the two timestamps, the day's hug count and the actor's comfort, and asks the rules everything
 * else.
 *
 * Nothing here can hurt anything. That is the contract: a cosy verb must never be a weapon with a nicer name, so
 * there is no damage, no knockback and no score in this file, and the comfort it gives is capped.
 *
 * Header-only and stateless apart from the actor itself, so a server and a client running the same seed and the
 * same inputs see the same small moment. */

#include <stdint.h>

/* PARENA-generated (packages/simulation/cozy_rules.c). */
int cozy_kick_cooldown_ms(void);
int cozy_kick_lift_milli(void);
int cozy_kick_puffs(int seed);
int cozy_kick_allowed(int is_dandelion, int cooldown_left_ms, int sun_permille);
int cozy_hug_cooldown_ms(void);
int cozy_hug_comfort_milli(void);
int cozy_hug_allowed(int trunk_milli, int cooldown_left_ms);
int cozy_hug_diminish(int hugs_today);
int cozy_comfort_target(int mood);
int cozy_comfort_drift(int comfort, int target, int ticks);
int cozy_line_count(void);
int cozy_line_index(int count, int seed);
int cozy_flavor_daylight(int sun_permille);
int cozy_trunk_huggable_milli(void);
int cozy_daylight_milli(void);

/* Moods, matching humanness.c, ambient_life.prn and wander: 0 IDLE 1 CURIOUS 2 BORED 3 TIRED 4 STARTLED. */
#define COZY_IDLE 0
#define COZY_CURIOUS 1
#define COZY_BORED 2
#define COZY_TIRED 3
#define COZY_STARTLED 4

typedef struct {
    int mood;
    int comfort;        /* 0..1000, drifting toward the mood's own target */
    int seed;           /* the actor's own seed: which puff, which reply */
    int kicks;          /* how many dandelions this actor has kicked (a stat, not a gate) */
    int hugs_today;     /* resets with the day: a tree forgives by morning */
    int last_kick_ms;
    int last_hug_ms;
    int started;        /* 1 once timestamps are meaningful; avoids a cooldown against time zero */
} CozyActor;

static inline int cozy_clamp(int lo, int hi, int v) {
    return v < lo ? lo : (v > hi ? hi : v);
}

static inline void cozy_actor_init(CozyActor *a, int mood, int seed) {
    a->mood = mood;
    a->comfort = cozy_comfort_target(mood);
    a->seed = seed < 0 ? 0 : seed;
    a->kicks = 0;
    a->hugs_today = 0;
    a->last_kick_ms = 0;
    a->last_hug_ms = 0;
    a->started = 0;
}

/* The rules' cooldown arithmetic, in one place so a host cannot get the sign wrong: a timestamp of 0 means
 * "never", which is NOT the same as "just now". `started` is what tells them apart -- without it the FIRST hug
 * is refused for the length of a cooldown measured from time zero, which is a real bug this flag exists for. */
static inline int cozy_cooldown_left(int now_ms, int last_ms, int ready, int started) {
    if (!started || !ready) return 0;
    int elapsed = now_ms - last_ms;
    return elapsed >= ready ? 0 : (ready - elapsed);
}

/* Kick a dandelion. Returns how many seeds came off (3..6) or 0 when the world said no -- night, not a dandelion,
 * or still on cooldown. Comfort rises by the rules' own lift, capped at 1000. */
static inline int cozy_try_kick(CozyActor *a, int is_dandelion, int now_ms, int sun_permille) {
    int left = cozy_cooldown_left(now_ms, a->last_kick_ms, cozy_kick_cooldown_ms(), a->started);
    if (cozy_kick_allowed(is_dandelion, left, sun_permille) != 1) return 0;
    int puffs = cozy_kick_puffs(a->seed);
    a->comfort = cozy_clamp(0, 1000, a->comfort + cozy_kick_lift_milli());
    a->seed = a->seed + 1;
    a->kicks++;
    a->last_kick_ms = now_ms;
    a->started = 1;
    return puffs;
}

/* Hug a tree. Returns the comfort actually gained, or 0 when refused (too thin a trunk, or still on cooldown).
 * The gain is the tree's worth scaled by how many hugs it has already given today, so the fifth is quiet. */
static inline int cozy_try_hug(CozyActor *a, int trunk_milli, int now_ms) {
    int left = cozy_cooldown_left(now_ms, a->last_hug_ms, cozy_hug_cooldown_ms(), a->started);
    if (cozy_hug_allowed(trunk_milli, left) != 1) return 0;
    int gain = (cozy_hug_comfort_milli() * cozy_hug_diminish(a->hugs_today)) / 1000;
    a->comfort = cozy_clamp(0, 1000, a->comfort + gain);
    a->hugs_today++;
    a->last_hug_ms = now_ms;
    a->started = 1;
    return gain;
}

/* Morning: the tree's count resets, because a grudge against a tree is not a thing anyone wants simulated. */
static inline void cozy_new_day(CozyActor *a) {
    a->hugs_today = 0;
}

/* Comfort drifts toward what this mood wants, one permille per tick, never overshooting. */
static inline void cozy_tick(CozyActor *a, int ticks) {
    a->comfort = cozy_comfort_drift(a->comfort, cozy_comfort_target(a->mood), ticks);
}

#endif
